CREATE OR REPLACE FUNCTION public.approve_payment_reconciliation_v2(p_review_id uuid, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare session_id uuid; r collect_security.reconciliation_reviews; p public.payments;
 reason_text text:=btrim(coalesce(p_reason,''));
begin
 session_id:=collect_security.require_reconciliation_actor();
 if p_review_id is null or length(reason_text) not between 10 and 500 then
  raise exception 'reconciliation_invalid_reason' using errcode='22023'; end if;
 select * into r from collect_security.reconciliation_reviews where id=p_review_id for update;
 if r.id is null or r.proposed_by=auth.uid() or r.consumed_at is not null
   or r.proposed_at<clock_timestamp()-interval '24 hours'
   or not isfinite(r.occurred_at) or r.occurred_at>clock_timestamp()+interval '5 minutes' then
  raise exception 'reconciliation_independent_approval_required' using errcode='22023'; end if;
 if not collect_security.reconciliation_actor_current(r.proposed_by,r.proposed_session_id) then
  raise exception 'reconciliation_actor_unavailable' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('provider-finality-payment:'||r.payment_id::text,0));
 select * into p from public.payments where id=r.payment_id for update;
 if p.id is null or p.status<>'review' or collect_security.reconciliation_fingerprint(p) is distinct from r.payment_fingerprint then
  raise exception 'reconciliation_payment_changed' using errcode='22023'; end if;
 if r.approved_by is not null then
  if r.approved_by=auth.uid() and r.approved_session_id=session_id and r.approval_reason=reason_text
     and r.approved_at>=clock_timestamp()-interval '15 minutes' then return true; end if;
  raise exception 'reconciliation_approval_conflict' using errcode='22023'; end if;
 update collect_security.reconciliation_reviews set approved_by=auth.uid(),approved_session_id=session_id,
  approved_at=clock_timestamp(),approval_reason=reason_text where id=r.id;
 perform public.create_audit_log('reconciliation.approved','payment',r.payment_id,
  jsonb_build_object('review_id',r.id,'evidence_sha256',r.evidence_sha256,'reason',reason_text,
    'session_id',session_id),auth.uid());
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.finalize_approved_reconciliation_v2(p_review_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r collect_security.reconciliation_reviews; p public.payments; result jsonb;
begin
 perform public._lock_notification_session_gate();
 if auth.role() is distinct from 'service_role' then raise exception 'reconciliation_service_required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
 select * into r from collect_security.reconciliation_reviews where id=p_review_id for update;
 if r.id is null or r.approved_by is null or r.approved_by=r.proposed_by
   or r.proposed_session_id is null or r.approved_session_id is null
   or not isfinite(r.occurred_at) or r.occurred_at>clock_timestamp()+interval '5 minutes' then
  raise exception 'reconciliation_approved_evidence_required' using errcode='22023'; end if;
 -- Recheck both recorded sessions as well as durable roles/identities.
 if not collect_security.reconciliation_actor_current(r.proposed_by,r.proposed_session_id)
   or not collect_security.reconciliation_actor_current(r.approved_by,r.approved_session_id) then
  raise exception 'reconciliation_actor_unavailable' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('provider-finality-payment:'||r.payment_id::text,0));
 select * into p from public.payments where id=r.payment_id for update;
 if r.consumed_at is not null then
  return jsonb_build_object('review_id',r.id,'payment_id',r.payment_id,'replayed',true,
    'payment_status',p.status,'evidence_level','independently_reconciled');
 end if;
 if r.approved_at<clock_timestamp()-interval '15 minutes' or r.proposed_at<clock_timestamp()-interval '24 hours' then
  raise exception 'reconciliation_approval_expired' using errcode='22023'; end if;
 if p.id is null or p.status<>'review' or collect_security.reconciliation_fingerprint(p) is distinct from r.payment_fingerprint then
  raise exception 'reconciliation_payment_changed' using errcode='22023'; end if;
 result:=public.process_provider_finality_event(r.id,'payment.confirmed',r.evidence_sha256,p.id,
   p.provider_network,p.transaction_id,r.source_reference,p.receiver_momo_number_hash,p.amount_rwf,
   r.occurred_at,r.evidence_sha256,null,null);
 update collect_security.reconciliation_reviews set consumed_at=clock_timestamp() where id=r.id;
 perform public.create_audit_log('reconciliation.finalized','payment',p.id,
  jsonb_build_object('review_id',r.id,'evidence_sha256',r.evidence_sha256,
    'proposed_by',r.proposed_by,'approved_by',r.approved_by),r.approved_by);
 return result||jsonb_build_object('review_id',r.id,'payment_status','posted','evidence_level','independently_reconciled');
end $function$

CREATE OR REPLACE FUNCTION public.propose_payment_reconciliation_v2(p_payment_id uuid, p_evidence_sha256 text, p_source_reference text, p_occurred_at timestamp with time zone, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare session_id uuid; payment_row public.payments; prior collect_security.reconciliation_reviews;
 result_id uuid; evidence text:=lower(btrim(coalesce(p_evidence_sha256,'')));
 reference_text text:=upper(btrim(coalesce(p_source_reference,''))); reason_text text:=btrim(coalesce(p_reason,''));
 fingerprint text;
begin
 session_id:=collect_security.require_reconciliation_actor();
 if p_payment_id is null or evidence !~ '^[a-f0-9]{64}$'
   or length(reference_text) not between 3 and 128 or length(reason_text) not between 10 and 500
   or p_occurred_at is null or not isfinite(p_occurred_at) or p_occurred_at>clock_timestamp()+interval '5 minutes' then
  raise exception 'reconciliation_invalid_evidence' using errcode='22023';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('provider-finality-payment:'||p_payment_id::text,0));
 select * into payment_row from public.payments where id=p_payment_id for update;
 if payment_row.id is null or payment_row.status<>'review' or payment_row.currency<>'RWF'
   or payment_row.provider_network not in ('mtn_momo','airtel_money')
   or payment_row.amount_rwf<=0 or payment_row.transaction_id is null
   or length(btrim(payment_row.transaction_id)) not between 3 and 128
   or payment_row.receiver_momo_number_hash is null or payment_row.receiver_momo_number_hash !~ '^[a-f0-9]{64}$' then
  raise exception 'reconciliation_payment_not_reviewable' using errcode='22023'; end if;
 fingerprint:=collect_security.reconciliation_fingerprint(payment_row);
 select * into prior from collect_security.reconciliation_reviews where payment_id=p_payment_id
   and proposed_by=auth.uid() and proposed_session_id=session_id and payment_fingerprint=fingerprint
   and evidence_sha256=evidence and source_reference=reference_text and occurred_at=p_occurred_at
   and proposal_reason=reason_text and consumed_at is null
   and proposed_at>=clock_timestamp()-interval '24 hours'
   and (approved_at is null or approved_at>=clock_timestamp()-interval '15 minutes')
   order by proposed_at desc,id limit 1;
 if prior.id is not null and (prior.approved_by is null
   or collect_security.reconciliation_actor_current(prior.approved_by,prior.approved_session_id)) then return prior.id; end if;
 insert into collect_security.reconciliation_reviews(payment_id,payment_fingerprint,evidence_sha256,
   source_reference,occurred_at,proposal_reason,proposed_by,proposed_session_id)
 values(p_payment_id,fingerprint,evidence,reference_text,p_occurred_at,reason_text,auth.uid(),session_id)
 returning id into result_id;
 perform public.create_audit_log('reconciliation.proposed','payment',p_payment_id,
  jsonb_build_object('review_id',result_id,'evidence_sha256',evidence,'source_reference',reference_text,
    'reason',reason_text,'session_id',session_id),auth.uid());
 return result_id;
end $function$

CREATE OR REPLACE FUNCTION public.confirm_provider_payment(p_payment_id uuid, p_provider_network text, p_transaction_id text, p_provider_confirmation_id text, p_receiver_momo_number_hash text, p_amount_rwf bigint, p_confirmed_at timestamp with time zone, p_evidence_sha256 text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  payment_row public.payments;
  clean_network text := lower(btrim(coalesce(p_provider_network, '')));
  clean_transaction_id text := upper(btrim(coalesce(p_transaction_id, '')));
  clean_confirmation_id text := upper(btrim(coalesce(p_provider_confirmation_id, '')));
  clean_receiver_hash text := lower(btrim(coalesce(p_receiver_momo_number_hash, '')));
  clean_evidence_hash text := lower(btrim(coalesce(p_evidence_sha256, '')));
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'Service role required'; end if;
  if p_payment_id is null
     or char_length(clean_network) not between 2 and 32
     or char_length(clean_transaction_id) not between 3 and 128
     or char_length(clean_confirmation_id) not between 3 and 128
     or clean_receiver_hash !~ '^[0-9a-f]{64}$'
     or p_amount_rwf is null or p_amount_rwf <= 0
     or p_confirmed_at is null or not isfinite(p_confirmed_at) or p_confirmed_at > now() + interval '5 minutes'
     or (clean_evidence_hash <> '' and clean_evidence_hash !~ '^[0-9a-f]{64}$') then
    raise exception 'Invalid provider confirmation';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('provider-finality-payment:' || p_payment_id::text, 0));

  select payment.* into payment_row
  from public.payments payment
  where payment.id = p_payment_id
  for update;
  if payment_row.id is null then raise exception 'Payment not found'; end if;
  if payment_row.status = 'posted' then
    if exists (
      select 1 from public.payment_provider_confirmations confirmation
      where confirmation.payment_id = payment_row.id
        and confirmation.provider_network = clean_network
        and upper(btrim(confirmation.provider_confirmation_id)) = clean_confirmation_id
        and upper(btrim(confirmation.transaction_id)) = clean_transaction_id
        and confirmation.receiver_momo_number_hash = clean_receiver_hash
        and confirmation.amount_rwf = p_amount_rwf
        and confirmation.confirmed_at = p_confirmed_at
        and confirmation.evidence_sha256 is not distinct from nullif(clean_evidence_hash, '')
    ) then return payment_row.id; end if;
    raise exception 'Payment was already finalized by a different confirmation';
  end if;
  if payment_row.status <> 'review' then
    raise exception 'Payment is not awaiting provider confirmation';
  end if;
  if lower(btrim(payment_row.provider_network)) is distinct from clean_network
     or upper(btrim(payment_row.transaction_id)) is distinct from clean_transaction_id
     or payment_row.receiver_momo_number_hash is distinct from clean_receiver_hash
     or payment_row.amount_rwf is distinct from p_amount_rwf then
    raise exception 'Provider confirmation does not match the payment candidate';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(clean_network || ':' || clean_transaction_id, 0));
  insert into public.payment_provider_confirmations(
    payment_id, provider_network, provider_confirmation_id, transaction_id,
    receiver_momo_number_hash, amount_rwf, confirmed_at, evidence_sha256
  ) values (
    payment_row.id, clean_network, clean_confirmation_id, clean_transaction_id,
    clean_receiver_hash, p_amount_rwf, p_confirmed_at, nullif(clean_evidence_hash, '')
  );
  insert into public.ledger_entries(
    payment_id, collection_id, user_id, member_record_id,
    entry_type, amount_rwf, visibility, metadata
  ) values
    (
      payment_row.id, payment_row.collection_id, payment_row.contributor_user_id,
      payment_row.member_record_id, 'collection_credit', payment_row.amount_rwf,
      'public_safe', jsonb_build_object(
        'allocation_method', 'provider_confirmed',
        'provider_confirmation_id', clean_confirmation_id
      )
    ),
    (
      payment_row.id, payment_row.collection_id, payment_row.contributor_user_id,
      payment_row.member_record_id, 'member_credit', payment_row.amount_rwf,
      'private', jsonb_build_object(
        'allocation_method', 'provider_confirmed',
        'provider_confirmation_id', clean_confirmation_id
      )
    );
  update public.payments
  set status = 'posted', posted_at = p_confirmed_at
  where id = payment_row.id;
  update public.parsed_payment_events
  set allocation_status = 'allocated',
      review_reason = 'Posted after independent provider confirmation'
  where id = payment_row.parsed_event_id;
  perform public.create_audit_log(
    'payment.provider_confirmed', 'payment', payment_row.id,
    jsonb_build_object(
      'provider_network', clean_network,
      'provider_confirmation_id', clean_confirmation_id,
      'confirmed_at', p_confirmed_at,
      'ledger_posted', true
    ),
    null
  );
  return payment_row.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.process_provider_finality_event(p_request_id uuid, p_event_type text, p_payload_sha256 text, p_payment_id uuid, p_provider_network text DEFAULT NULL::text, p_transaction_id text DEFAULT NULL::text, p_provider_confirmation_id text DEFAULT NULL::text, p_receiver_momo_number_hash text DEFAULT NULL::text, p_amount_rwf bigint DEFAULT NULL::bigint, p_occurred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_evidence_sha256 text DEFAULT NULL::text, p_rejection_reason text DEFAULT NULL::text, p_provider_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  clean_event_type text := btrim(coalesce(p_event_type, ''));
  clean_payload_sha256 text := lower(btrim(coalesce(p_payload_sha256, '')));
  existing_request public.provider_finality_requests;
  inserted_request_id uuid;
  finalized_payment_id uuid;
  stored_reference text;
  bound_input_sha256 text;
  clean_network text := nullif(lower(btrim(coalesce(p_provider_network, ''))), '');
  clean_transaction text := nullif(upper(btrim(coalesce(p_transaction_id, ''))), '');
  clean_confirmation text := nullif(upper(btrim(coalesce(p_provider_confirmation_id, ''))), '');
  clean_receiver text := nullif(lower(btrim(coalesce(p_receiver_momo_number_hash, ''))), '');
  clean_evidence text := nullif(lower(btrim(coalesce(p_evidence_sha256, ''))), '');
  clean_reason text := nullif(btrim(coalesce(p_rejection_reason, '')), '');
  clean_reference text := nullif(btrim(coalesce(p_provider_reference, '')), '');
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'Service role required'; end if;
  if p_request_id is null or p_payment_id is null
     or clean_event_type not in ('payment.confirmed', 'payment.rejected')
     or clean_payload_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'Invalid provider finality request';
  end if;
  stored_reference := case
    when clean_event_type = 'payment.confirmed'
      then clean_confirmation
    else clean_reference
  end;

  -- Epoch binds the instant independently of the caller's session TimeZone.
  bound_input_sha256 := encode(extensions.digest(jsonb_build_object(
    'contract', 1, 'event_type', clean_event_type, 'payment_id', p_payment_id,
    'network', clean_network, 'transaction_id', clean_transaction,
    'confirmation_id', clean_confirmation, 'receiver_hash', clean_receiver,
    'amount_rwf', p_amount_rwf, 'occurred_at_epoch', extract(epoch from p_occurred_at),
    'evidence_sha256', clean_evidence, 'rejection_reason', clean_reason,
    'provider_reference', clean_reference
  )::text, 'sha256'), 'hex');

  perform pg_advisory_xact_lock(
    hashtextextended('provider-finality-payment:' || p_payment_id::text, 0)
  );

  insert into public.provider_finality_requests(
    request_id, event_type, payload_sha256, payment_id, provider_network, provider_reference, input_sha256
  ) values (
    p_request_id, clean_event_type, clean_payload_sha256, p_payment_id,
    clean_network, stored_reference, bound_input_sha256
  )
  on conflict (request_id) do nothing
  returning request_id into inserted_request_id;
  if inserted_request_id is null then
    select request.* into existing_request
    from public.provider_finality_requests request
    where request.request_id = p_request_id
    for update;
    if existing_request.input_sha256 is null then
      raise exception 'Legacy provider finality request requires reconciliation';
    end if;
    if existing_request.event_type <> clean_event_type
       or existing_request.payload_sha256 <> clean_payload_sha256
       or existing_request.payment_id <> p_payment_id
       or existing_request.input_sha256 is distinct from bound_input_sha256 then
      raise exception 'Provider finality request id was reused with different content';
    end if;
    if existing_request.status <> 'processed' or existing_request.result_payment_id is null then
      raise exception 'Provider finality request is not complete';
    end if;
    return jsonb_build_object('payment_id', existing_request.result_payment_id, 'replayed', true);
  end if;
  if clean_event_type = 'payment.confirmed' then
    finalized_payment_id := public.confirm_provider_payment(
      p_payment_id, p_provider_network, p_transaction_id,
      p_provider_confirmation_id, p_receiver_momo_number_hash,
      p_amount_rwf, p_occurred_at, p_evidence_sha256
    );
  else
    finalized_payment_id := collect_hybrid.reject_bound_provider_payment(
      p_payment_id, p_provider_network, p_transaction_id, p_receiver_momo_number_hash,
      p_amount_rwf, p_occurred_at, p_evidence_sha256, p_rejection_reason, p_provider_reference
    );
  end if;
  update public.provider_finality_requests
  set status = 'processed', result_payment_id = finalized_payment_id, processed_at = now()
  where request_id = p_request_id;
  return jsonb_build_object('payment_id', finalized_payment_id, 'replayed', false);
end;
$function$
